import json
res=json.load(open('sweep_h8_results.json'))
out={'variant':'H8-sweep','configs':[]}
for r in res:
    rm=r['rules_mean']; b=r['boot']
    c={'label':r['label'],'square':round(rm['square'],3),'quartic':round(rm['quartic'],3),
       'equal':round(rm['equal'],3),'sw_mean':round(r['sw_mean'],3)}
    for tag in ('g8','g10'):
        v=b['vs_'+tag]
        c['vs_'+tag]={'delta':round(v['delta'],3),'lo':round(v['lo'],3),'hi':round(v['hi'],3),'p_pos':round(v['p_pos'],3)}
    out['configs'].append(c)
print(json.dumps(out,ensure_ascii=False))
"
